SELECT 
FROM sys_business_resource_binding


        AND business_config_id = #{businessConfigId}


        AND resource_type = #{resourceType}


        AND resource_id LIKE CONCAT('%', #{resourceId}, '%')


        AND resource_name LIKE CONCAT('%', #{resourceName}, '%')


        AND binding_type = #{bindingType}


        AND binding_priority = #{bindingPriority}


        AND is_active = #{isActive}


        AND create_user_id = #{createUserId}


        AND update_user_id = #{updateUserId}


        AND create_time >= #{createTime}


        AND update_time >= #{updateTime}


ORDER BY create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(1)
FROM sys_business_resource_binding


        AND business_config_id = #{businessConfigId}


        AND resource_type = #{resourceType}


        AND resource_id LIKE CONCAT('%', #{resourceId}, '%')


        AND resource_name LIKE CONCAT('%', #{resourceName}, '%')


        AND binding_type = #{bindingType}


        AND binding_priority = #{bindingPriority}


        AND is_active = #{isActive}


        AND create_user_id = #{createUserId}


        AND update_user_id = #{updateUserId}

SELECT b.id, b.business_config_id, b.resource_type, b.resource_id, b.resource_name, b.binding_type, b.binding_priority, b.is_active, b.metadata, b.create_user_id, b.update_user_id, b.create_time, b.update_time FROM sys_business_resource_binding b INNER JOIN sys_business_config c ON b.business_config_id = c.id WHERE c.code = #{businessCode}
AND b.resource_type = #{resourceType}
AND b.is_active = TRUE ORDER BY b.binding_priority ASC

